using System.Collections.Generic;
using UnityEngine;

public class AirWalkEmitter : ParticleEffect
{
	public static Dictionary<Vector2, float> _airWalkTimestamps;

	private GameObject mainRoomObj;

	private string mainRoomObjLevelName;

	private float timeStampThreshold = 0.75f;

	public static Dictionary<Vector2, float> AirWalkTimestamps
	{
		get
		{
			if (_airWalkTimestamps == null)
			{
				_airWalkTimestamps = new Dictionary<Vector2, float>();
			}
			return _airWalkTimestamps;
		}
	}

	public void EmitSingle(int? particleCount = null, Vector3? position = null, ParticleSystemOverride overrides = null, Vector3? localEulerAngles = null, float delayTime = 0f, float? sortYOffset = null)
	{
		Vector2 key = ((Vector2?)position) ?? default(Vector2);
		key += new Vector2(0.5f, -0.5f);
		Vector3? vector = position;
		position = ((!vector.HasValue) ? ((Vector3?)null) : new Vector3?(vector.GetValueOrDefault() + new Vector3(0.5f, -0.5f, 0f)));
		if (!NextLevelLoader.InTierScene(string.Empty))
		{
			if (mainRoomObj == null || Application.loadedLevelName != mainRoomObjLevelName)
			{
				Room[] array = Object.FindObjectsOfType<Room>();
				for (int i = 0; i < array.Length; i++)
				{
					if (array[i].gameObject.activeSelf)
					{
						mainRoomObj = array[i].gameObject;
						break;
					}
				}
			}
			if (mainRoomObj != null)
			{
				key += (Vector2)mainRoomObj.transform.position;
				Vector3? vector2 = position;
				position = ((!vector2.HasValue) ? ((Vector3?)null) : new Vector3?(vector2.GetValueOrDefault() + mainRoomObj.transform.position));
			}
		}
		if (!AirWalkTimestamps.ContainsKey(key) || !(Time.time - AirWalkTimestamps[key] < timeStampThreshold))
		{
			AirWalkTimestamps[key] = Time.time;
			base.Emit(particleCount, position, overrides, localEulerAngles, delayTime, sortYOffset);
		}
	}
}
using Chaos.AnimatorExtensions;
using UnityEngine;

public class AnimEffect : MonoBehaviour
{
	public Animator anim;

	public string defaultAnimName = string.Empty;

	private Vector3 initialLocalEulerAngles;

	public bool playing;

	public bool skipAnimCheck;

	public bool ignoreAnimCheck;

	private string queuedAnimName;

	private float queuedAnimTime;

	private float queuedAnimSpeed = 1f;

	public virtual void Awake()
	{
		anim = GetComponentInChildren<Animator>();
		initialLocalEulerAngles = transform.localEulerAngles;
	}

	private void Start()
	{
		if (!playing)
		{
			gameObject.SetActive(value: false);
		}
	}

	public virtual void Play(Vector3 position = default(Vector3), string animName = "", float normalizedTime = 0f, Vector2 randomStartingRange = default(Vector2), float animSpeed = 1f, float givenScale = 1f, Vector3? localEulerAngles = null)
	{
		gameObject.SetActive(value: true);
		playing = true;
		transform.position = position;
		transform.localScale = Vector3.one * givenScale;
		if (randomStartingRange != Vector2.zero)
		{
			normalizedTime = Random.Range(randomStartingRange.x, randomStartingRange.y);
		}
		transform.localEulerAngles = initialLocalEulerAngles;
		if (localEulerAngles.HasValue)
		{
			transform.localEulerAngles = localEulerAngles.Value;
		}
		if (animName == string.Empty)
		{
			animName = defaultAnimName;
		}
		queuedAnimName = animName;
		queuedAnimTime = normalizedTime;
		queuedAnimSpeed = animSpeed;
		skipAnimCheck = true;
	}

	public void PlayAnim(string animName, float normalizedTime = 0f)
	{
		gameObject.SetActive(value: true);
		playing = true;
		anim.Play(animName, -1, normalizedTime);
		queuedAnimName = animName;
		queuedAnimTime = normalizedTime;
		queuedAnimSpeed = 1f;
		skipAnimCheck = true;
	}

	private void LateUpdate()
	{
		if (playing && gameObject.activeSelf && queuedAnimName != null)
		{
			anim.speed = queuedAnimSpeed;
			anim.Play(queuedAnimName, -1, queuedAnimTime);
			queuedAnimName = null;
			queuedAnimTime = 0f;
			queuedAnimSpeed = 1f;
		}
		else if (!ignoreAnimCheck)
		{
			if (skipAnimCheck)
			{
				skipAnimCheck = false;
			}
			else if (playing && anim.AnimPlayed())
			{
				gameObject.SetActive(value: false);
				playing = false;
			}
		}
	}

	public float GetAnimTime()
	{
		return anim.GetAnimTime();
	}
}
using System;
using UnityEngine;

[Serializable]
public class AuxParticleEffect
{
	public string effectName;

	public int particleCount = 10;

	public ParticleSystemOverride overrides;

	public Vector3 localEulerAngles;

	public float delayTime;

	public float sortYOffset;

	public Vector3 positionOffset;

	public Transform followTransform;

	public AuxParticleEffect(string effectName, int? particleCount = null, Vector3? position = null, ParticleSystemOverride overrides = null, Vector3? localEulerAngles = null, float delayTime = 0f, float? sortYOffset = null, Vector3? positionOffset = null, Transform followTransform = null)
	{
		this.effectName = effectName;
		if (particleCount.HasValue)
		{
			this.particleCount = particleCount.Value;
		}
		if (overrides != null)
		{
			this.overrides = overrides;
		}
		if (localEulerAngles.HasValue)
		{
			this.localEulerAngles = localEulerAngles.Value;
		}
		this.delayTime = delayTime;
		if (sortYOffset.HasValue)
		{
			this.sortYOffset = sortYOffset.Value;
		}
		if (positionOffset.HasValue)
		{
			this.positionOffset = positionOffset.Value;
		}
		if (followTransform != null)
		{
			this.followTransform = followTransform;
		}
	}
}
using Chaos.AnimatorExtensions;
using UnityEngine;

public class CircleOutlineEffect : MonoBehaviour
{
	private Animator anim;

	private bool playing;

	private float animEndTime = 1f;

	private float animStartTime;

	private bool firstFrameSkipped;

	private Material spriteMaterial;

	private float dissolveThreshold = 0.6f;

	private float dissolveTime;

	private void Awake()
	{
		anim = GetComponent<Animator>();
		spriteMaterial = GetComponentInChildren<SpriteRenderer>().material;
	}

	public void Update()
	{
		if (playing && firstFrameSkipped)
		{
			float animTime = anim.GetAnimTime();
			if (animTime >= animEndTime)
			{
				Reset();
			}
			else if (animTime >= dissolveTime)
			{
				spriteMaterial.SetFloat("_DissolveAmount", Globals.LerpWithRange(dissolveTime, animEndTime, animTime));
			}
		}
	}

	public void LateUpdate()
	{
		if (playing && !firstFrameSkipped)
		{
			firstFrameSkipped = true;
		}
	}

	public void Play(Vector3 position, float animSpeed = 1f, float animStartTime = 0f, float animEndTime = 1f)
	{
		transform.position = position;
		this.animEndTime = animEndTime;
		this.animStartTime = animStartTime;
		anim.speed = animSpeed;
		dissolveTime = animEndTime * dissolveThreshold;
		anim.Play("Grow", -1, animStartTime);
		playing = true;
		firstFrameSkipped = false;
		spriteMaterial.SetFloat("_DissolveAmount", 0f);
		transform.Rotate(Vector3.forward, 90 * Random.Range(0, 3));
	}

	public void Reset()
	{
		playing = false;
		firstFrameSkipped = false;
		anim.speed = 1f;
		animEndTime = 1f;
		animStartTime = 1f;
		dissolveTime = dissolveThreshold;
		anim.Play("Idle", -1, 0f);
		spriteMaterial.SetFloat("_DissolveAmount", 0f);
	}
