	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/EarthWheel.prefab");
			}
			return _prefab;
		}
	}
	private void Start()
	{
		PlayAnim();
		Activate();
	}
	private void PlayAnim()
	{
		animStr = ((!largeVersion) ? "Small" : string.Empty);
		float num = Vector2.Angle(Vector2.up, targetVector);
		bool flag = targetVector.x >= 0f;
		if (num <= 30f)
		{
			animStr += "SpawnUp";
			floorCrackOffset = Vector2.up;
		}
		else if (num <= 60f)
		{
			animStr += "SpawnUpRight";
			floorCrackOffset = Vector2.one;
		}
		else if (num <= 120f)
		{
			animStr += "SpawnRight";
			floorCrackOffset = Vector2.right;
		}
		else if (num <= 150f)
		{
			animStr += "SpawnUpRight";
			floorCrackOffset = new Vector2(1f, -1f);
			if (flag)
			{
				spriteRenderer.transform.localEulerAngles = new Vector3(0f, 0f, -90f);
			}
			else
			{
				spriteRenderer.transform.localEulerAngles = new Vector3(0f, 0f, 90f);
			}
		}
		else
		{
			animStr += "SpawnUp";
			floorCrackOffset = Vector2.up;
		}
		if (!flag)
		{
			spriteRenderer.transform.localScale = Globals.Vector3NegativeX;
			floorCrackOffset.x *= -1f;
		}
		anim.Play(animStr, -1, 0f);
		currentPosition = transform.position;
		floorCrackOffset = floorCrackOffset.normalized * ((!largeVersion) ? 0.5f : 0.9f);
		PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, currentPosition);
		PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, currentPosition + floorCrackOffset);
		PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, currentPosition - floorCrackOffset);
		PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(4, currentPosition, RockDebrisEmitter.CircleExplosionOverride);
	}
	private void Activate()
	{
		lifeTimer.IsRunning = true;
		speedUpTimer.IsRunning = true;
		spinTimer.IsRunning = true;
		trailTimer.IsRunning = true;
		movement.moveSpeedStat.SetInitialBaseValue(0f);
		moveSpeedMod = new NumVarStatMod("EarthWheelSpeedMod", 0f, 10, VarStatModType.Override);
		movement.moveSpeedStat.AddMod(moveSpeedMod);
		movement.moveVector = targetVector;
		if (!largeVersion)
		{
			atkCollider.transform.localScale *= 0.75f;
			preventFallCollider.transform.localScale *= 0.75f;
		}
		preventFallCollider.transform.localEulerAngles = Globals.GetRotationVector(targetVector);
		atkCollider.transform.localEulerAngles = Globals.GetRotationVector(targetVector);
		Attack attack = this.attack;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(EntityHit));
		atkCollider.enabled = true;
		SoundManager.PlayAudioWithDistance("EarthCrumble", transform.position, null, 24f, -1f, 1.1f);
	}
	private void Update()
	{
		if (!destroyQueued)
		{
			HandleEffects(transform.position);
		}
	}
	private void FixedUpdate()
	{
		if (destroyQueued)
		{
			return;
		}
		if (!spinCompleted)
		{
			spinLerpValue = spinTimer.TimePercentage;
			anim.speed = Mathf.Lerp(0f, maxAnimSpeed, spinLerpValue);
			spinCompleted = spinLerpValue >= 1f;
			return;
		}
		movement.MoveToMoveVector();
		if (!entityHit)
		{
			if (!speedUpCompleted)
			{
				speedUpLerpVal = speedUpTimer.TimePercentage;
				moveSpeedMod.modValue = Mathf.Lerp(minMoveSpeed, maxMoveSpeed, Globals.GetSmoothLerpValue(speedUpLerpVal));
				movement.moveSpeedStat.AddMod(moveSpeedMod);
				speedUpCompleted = speedUpLerpVal >= 1f;
				if (usingSlowTrailInterval && speedUpLerpVal > 0.13f && trailTimer.Delay == trailIntervalSlow)
				{
					usingSlowTrailInterval = false;
					trailTimer.SetDelay(trailIntervalFast);
				}
			}
			if (!lifeTimer.IsRunning)
			{
				Disable();
			}
		}
		else
		{
			switch (ChaosStopwatch.CheckInterval(hitCDStopwatchID))
			{
			case StopwatchState.Running:
				attack.collider.enabled = true;
				break;
			case StopwatchState.Ready:
				attack.collider.enabled = false;
				break;
			case StopwatchState.Done:
				Disable();
				break;
			}
		}
	}
	private void Disable()
	{
		destroyQueued = true;
		attack.collider.enabled = false;
		currentPosition = transform.position;
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 30;
		float scale = 0.2f;
		float startSpeed = 5f;
		Vector3? emitPosition = currentPosition;
