		PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(4, currentPosition - targetVector * 0.5f, RockDebrisEmitter.SmallCircleExplosionOverride);
		PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(4, currentPosition + targetVector * 0.5f, RockDebrisEmitter.SmallCircleExplosionOverride);
		PoolManager.GetPoolItem<RockMedDebrisEmitter>().EmitSingle(4, currentPosition, RockDebrisEmitter.SmallCircleExplosionOverride);
		if (wheelAudio != null && wheelAudio.isPlaying)
		{
			wheelAudio.Stop();
		}
		string audioID = "RockFormShort";
