using System;
public class FixedSizeQueue<T>
{
	private int index;
	private T[] array;
	private int length;
	public int Length => length;
	public FixedSizeQueue(int givenLength)
	{
		length = givenLength;
		array = new T[givenLength];
		index = 0;
	}
	public void Enqueue(T obj)
	{
		array[index] = obj;
		index++;
		if (index >= length)
		{
			index -= length;
		}
	}
	public T GetAtIndex(int givenIndex)
	{
		return array[givenIndex % length];
	}
	public T[] GetArray()
	{
		return array;
	}
	public void Clear()
	{
		Array.Clear(array, 0, length);
	}
}
