	{
		string text = string.Empty;
		switch (effectType)
		{
		case FloorCrackEffectType.Medium:
			text += "Med";
			break;
		case FloorCrackEffectType.Small:
			text += "Small";
			break;
		}
		text = ((!crackMode) ? (text + "Fade") : (text + "Crack"));
		animName = text;
	}
	public void Crack(Vector3 position, float animDuration = -1f, float autoFadeTime = 0.75f, float fadeDuration = 0.5f, FloorCrackEffectType effectType = FloorCrackEffectType.Default)
	{
		gameObject.SetActive(value: true);
		transform.position = position;
		if (Random.value > 0.5f)
		{
			transform.localScale = new Vector3(0f - transform.localScale.x, transform.localScale.y, transform.localScale.z);
		}
		if (animDuration == -1f)
		{
			animDuration = defaultCrackDuration;
		}
		this.effectType = effectType;
		SetAnimName();
		if (animDuration == 0f)
		{
			anim.Play(animName, -1, 1f);
		}
		else
		{
			anim.AdjustAnimSpeed(animName, animDuration);
			anim.Play(animName);
		}
		if (autoFadeTime != -1f)
		{
			if (fadeDuration != -1f)
			{
				currentFadeDuration = fadeDuration;
			}
			else
			{
				currentFadeDuration = defaultFadeDuration;
			}
			Invoke("Fade", animDuration + autoFadeTime);
		}
	}
	public void Fade()
	{
		Fade(currentFadeDuration);
	}
	public void Fade(float fadeDuration = -1f)
	{
		if (fadeDuration == -1f)
		{
			fadeDuration = defaultFadeDuration;
		}
		if (fadeDuration == 0f)
		{
			Idle();
		}
		SetAnimName(crackMode: false);
		anim.AdjustAnimSpeed(animName, fadeDuration);
		anim.Play(animName);
		CancelInvoke("Fade");
	}
	public void Idle()
	{
		anim.speed = 1f;
		anim.Play("Idle");
		CancelInvoke("Fade");
	}
	public void Reset()
	{
		Idle();
		currentFadeDuration = defaultFadeDuration;
