	public virtual void Emit(int? particleCount = null, Vector3? position = null, ParticleSystemOverride overrides = null, Vector3? localEulerAngles = null, float delayTime = 0f, float? sortYOffset = null, Transform followTransform = null)
	{
		if (gameObject != null)
		{
			gameObject.SetActive(value: true);
		}
		if (delayTime > 0f)
		{
			delayRunning = true;
			StartCoroutine(EmitDelayed(delayTime, particleCount, position, overrides, localEulerAngles));
			return;
		}
		calcParticleCount = (particleCount.HasValue ? particleCount.Value : defaultParticleCount);
		if (calcParticleCount == 0)
		{
			return;
		}
		effectEmitter.LoadSnapshot(initialSettings);
		ResetParticleSorter(sortYOffset);
		if (position.HasValue)
		{
			effectEmitter.transform.position = position.Value;
		}
		this.followTransform = null;
		if (followTransform != null)
		{
			this.followTransform = followTransform;
			effectEmitter.transform.position = this.followTransform.position;
		}
		effectEmitter.ApplyOverrides(overrides);
		if (localEulerAngles.HasValue)
		{
			transform.localEulerAngles = localEulerAngles.Value;
		}
		effectEmitter.Emit(calcParticleCount);
		if (soundOnEmit != null && soundOnEmit.Length >= 1 && soundEmitCount > 0)
		{
			for (int i = 0; i < soundEmitCount; i++)
			{
				SoundManager.PlayAudioWithDistance(soundOnEmit.GetRandomValue(), transform.position);
			}
		}
		if (auxParticleEffects != null && auxParticleEffects.Length > 0)
		{
			for (int j = 0; j < auxParticleEffects.Length; j++)
			{
				AuxParticleEffect auxParticleEffect = auxParticleEffects[j];
				PoolManager.GetPoolItem<ParticleEffect>(auxParticleEffect.effectName).Emit(auxParticleEffect.particleCount, (!position.HasValue) ? ((Vector3?)null) : new Vector3?(position.GetValueOrDefault() + auxParticleEffect.positionOffset), auxParticleEffect.overrides, auxParticleEffect.localEulerAngles, auxParticleEffect.delayTime, auxParticleEffect.sortYOffset, auxParticleEffect.followTransform);
