		if (delayTime > 0f)
		{
			delayRunning = true;
			StartCoroutine(PlayDelayed(delayTime, emissionRate, position, overrides, playTime, followTransform, localEulerAngles));
			return;
		}
		effectEmitter.LoadSnapshot(initialSettings);
		ResetParticleSorter();
		if (emissionRate.HasValue)
		{
			effectEmitter.emissionRate = emissionRate.Value;
		}
		effectEmitter.loop = loop;
		if (position.HasValue)
		{
			effectEmitter.transform.position = position.Value;
		}
		if (localEulerAngles.HasValue)
		{
			transform.localEulerAngles = localEulerAngles.Value;
		}
		if (followTransform != null)
		{
			this.followTransform = followTransform;
		}
		if (this.followTransform != null)
		{
			effectEmitter.transform.position = this.followTransform.position;
		}
		effectEmitter.ApplyOverrides(overrides);
		emissionMod.enabled = true;
		effectEmitter.Play();
		if (playTime.HasValue)
		{
			playTimerID = ChaosStopwatch.Begin(playTime.Value);
		}
		playing = true;
	}
	private IEnumerator PlayDelayed(float delayTime, float? emissionRate = null, Vector3? position = null, ParticleSystemOverride overrides = null, float? playTime = null, Transform followTransform = null, Vector3? localEulerAngles = null)
	{
		yield return new WaitForSeconds(delayTime);
		delayRunning = false;
		Play(emissionRate, position, overrides, playTime, followTransform, localEulerAngles);
	}
	public virtual void Stop()
	{
		playing = false;
		followTransform = null;
		reqFollowTrans = false;
		playTimerID = -1;
		emissionMod.enabled = false;
		effectEmitter.Stop();
		if (hasSubmitters && subEmitters != null)
		{
			for (int i = 0; i < subEmitters.Length; i++)
			{
				subEmitters[i].Stop();
			}
		}
	}
	public void ClearAll()
	{
		effectEmitter.Clear();
		if (hasSubmitters && subEmitters != null)
		{
			for (int i = 0; i < subEmitters.Length; i++)
			{
