			}
		}
	}
	public void Update()
	{
		if (playing && playTimerID != -1 && ChaosStopwatch.Check(playTimerID))
		{
			Stop();
		}
		if (delayRunning || effectEmitter == null || effectEmitter.isPlaying)
		{
