				}
			}
		}
		gameObject.SetActive(value: false);
	}
	public void LateUpdate()
	{
		if (followTransform != null)
		{
			effectEmitter.transform.position = followTransform.position + followOffset;
		}
		else if (playing && reqFollowTrans)
		{
