		}
	}
	public void SetSortLayer(string layerName)
	{
		effectEmitter.GetComponent<Renderer>().sortingLayerName = layerName;
	}
	public void SetStartRotation(float rotation)
	{
		tempOverride.startRotation = 0f - (float)Math.PI / 180f * rotation;
