	private void Start()
	{
		pSysArray = GetComponentsInChildren<ParticleSystem>();
		pSysCount = pSysArray.Length;
		pSysShapeArray = new ParticleSystem.ShapeModule[pSysCount];
		pSysMainArray = new ParticleSystem.MainModule[pSysCount];
		pSysEmissionArray = new ParticleSystem.EmissionModule[pSysCount];
		for (int i = 0; i < pSysCount; i++)
		{
			ref ParticleSystem.ShapeModule reference = ref pSysShapeArray[i];
			reference = pSysArray[i].shape;
			pSysShapeArray[i].radius = startRadius;
			ref ParticleSystem.MainModule reference2 = ref pSysMainArray[i];
			reference2 = pSysArray[i].main;
			ref ParticleSystem.EmissionModule reference3 = ref pSysEmissionArray[i];
			reference3 = pSysArray[i].emission;
			pSysEmissionArray[i].enabled = false;
		}
	}
	private void Update()
	{
		if (parentTrans == null)
		{
			Stop();
			return;
		}
		if (ChaosStopwatch.Check(vortexStopwatchID))
		{
			PlayImmediate();
		}
		if (isPlaying)
		{
			calcRadius = Mathf.Lerp(startRadius, endRadius, ChaosStopwatch.GetTimePercentage(vortexStopwatchID));
			for (int i = 0; i < pSysCount; i++)
			{
				pSysShapeArray[i].radius = calcRadius;
			}
		}
	}
	public void Play(Transform givenTrans, float delayTime = 0f)
	{
		if (!(givenTrans == null))
		{
			parentTrans = givenTrans;
			transform.position = parentTrans.position;
			if (delayTime <= 0f)
			{
				PlayImmediate();
			}
			else
			{
				SetPlayVars(delayTime);
			}
		}
	}
	private void PlayImmediate()
	{
		isPlaying = true;
		SetPlayVars(rotationTime);
		for (int i = 0; i < pSysCount; i++)
		{
			pSysShapeArray[i].radius = startRadius;
			pSysEmissionArray[i].enabled = true;
			pSysMainArray[i].simulationSpeed = 1f / rotationTime;
			pSysArray[i].Play(withChildren: false);
		}
	}
	private void SetPlayVars(float givenTime)
	{
		gameObject.SetActive(value: true);
		vortexStopwatchID = ChaosStopwatch.Begin(givenTime);
		if (startAngleRange.x == startAngleRange.y)
		{
			transform.localEulerAngles = new Vector3(0f, 0f, startAngleRange.x);
		}
		else
		{
			transform.localEulerAngles = new Vector3(0f, 0f, Random.Range(startAngleRange.x, startAngleRange.y));
		}
	}
	public void Stop()
	{
		isPlaying = false;
		ChaosStopwatch.Stop(vortexStopwatchID);
		for (int i = 0; i < pSysCount; i++)
		{
			pSysEmissionArray[i].enabled = false;
			pSysArray[i].Stop(withChildren: false);
