	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/Effects/PoisonEffect.prefab");
			}
			return _prefab;
		}
	}
	private void SetColor(PoisonType pType = PoisonType.Green)
	{
		switch (pType)
		{
		case PoisonType.Green:
			fgEmitterMain.startColor = PoisonCircle.greenEffectColor;
			bgEmitterMain.startColor = PoisonCircle.greenEffectColor;
			break;
		case PoisonType.DarkGreen:
			fgEmitterMain.startColor = PoisonCircle.greenEffectColor;
			bgEmitterMain.startColor = PoisonCircle.greenEffectColor;
			break;
		default:
			fgEmitterMain.startColor = PoisonCircle.purpleEffectColor;
			bgEmitterMain.startColor = PoisonCircle.purpleEffectColor;
			break;
		}
	}
	private void Awake()
	{
		particleSystems = GetComponentsInChildren<ParticleSystem>();
		emissionMods = new ParticleSystem.EmissionModule[particleSystems.Length];
		mainMods = new ParticleSystem.MainModule[particleSystems.Length];
		for (int i = 0; i < particleSystems.Length; i++)
		{
			ref ParticleSystem.EmissionModule reference = ref emissionMods[i];
			reference = particleSystems[i].emission;
			ref ParticleSystem.MainModule reference2 = ref mainMods[i];
			reference2 = particleSystems[i].main;
		}
		bgEmitterMain = bgEmitter.main;
		fgEmitterMain = fgEmitter.main;
		skullEmitterMain = skullEmitter.main;
	}
	private void Start()
	{
		SetColor(poisonType);
		if (worldSpaceSkulls)
		{
			ParticleSystem.MainModule main = skullEmitter.main;
			main.simulationSpace = ParticleSystemSimulationSpace.World;
		}
		for (int i = 0; i < mainMods.Length; i++)
		{
			if (!prewarm || !worldSpace)
			{
				particleSystems[i].Stop();
				particleSystems[i].Clear();
				mainMods[i].prewarm = prewarm;
				mainMods[i].simulationSpace = (worldSpace ? ParticleSystemSimulationSpace.World : ParticleSystemSimulationSpace.Local);
			}
			particleSystems[i].Play();
		}
	}
	public override void Disable()
	{
		if (gameObject != null)
		{
			for (int i = 0; i < particleSystems.Length; i++)
			{
				emissionMods[i].enabled = false;
				particleSystems[i].Stop();
			}
			Object.Destroy(gameObject, destroyDelay);
		}
	}
	public void DisableSkullEmitter()
	{
		ParticleSystem.EmissionModule emission = skullEmitter.emission;
		emission.enabled = false;
		skullEmitter.Stop();
	}
